"""Automated reproduction test generated by Issue #18 On-Call Agent."""

from pathlib import Path
import pytest
from app.storage.local import LocalStorage


def test_storage_save_auto_creates_missing_root_directory(tmp_path: Path) -> None:
    """Verify that LocalStorage.save resiliently creates missing root storage directory.

    Before fix: If the storage directory is removed or not created prior to save,
    LocalStorage.save() crashes with FileNotFoundError.
    After fix: LocalStorage.save() ensures self.root exists and successfully stores the file.
    """
    root = tmp_path / "missing_reports_dir"
    storage = LocalStorage(root=root)
    # Remove directory to simulate runtime storage path disruption
    if root.exists():
        root.rmdir()
    assert not root.exists(), "Storage directory should not exist prior to save"

    stored = storage.save([b"%PDF-1.4 test report content"])
    assert root.exists(), "Storage directory must be auto-created by save()"
    assert stored.key.endswith(".pdf")
    assert stored.size_bytes > 0
